<!doctype html><html lang="id"><head><?php render_head('AgroTrack - Data Pengguna'); ?></head><body data-portal="admin" data-active="pengguna" data-base="../../"><?php render_sidebar($user,'pengguna');?><main class="app-main"><div class="topbar"><div><h1 class="page-title">Data Pengguna</h1><p class="page-kicker">Kelola akses dan akun pengguna AgroTrack.</p></div></div><section class="panel"><div class="d-flex justify-content-between mb-3"><h2 class="section-title mb-0">Daftar Pengguna</h2><input class="form-control w-auto" data-table-search="#userTable" placeholder="Cari pengguna..." /></div><div class="table-responsive"><table class="table admin-table" id="userTable"><thead><tr><th>Nama & Email</th><th>Role</th><th>Status</th><th>Lahan</th><th>Tgl Daftar</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="d-flex align-items-center gap-2"><img class="user-avatar" src="../../<?=e($r['profile_photo']?:'assets/image/profil/farmer-profile.jpg')?>" alt="<?=e($r['name'])?>" /><span><strong><?=e($r['name'])?></strong><br><small class="text-secondary"><?=e($r['email'])?></small></span></div></td><td><?=e($r['role'])?></td><td><span class="status-dot"><?=e($r['status'])?></span></td><td><?=e($r['total_lahan'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></main><script src="../../assets/js/app.js"></script></body></html>
